// Verbia UI strings. Every language must stay symmetric — all of them carry
// the same key set as EN. Brand copy (slogan / UX line) has official
// bilingual versions; UI copy follows the chosen interface language
// (UserSettings.uiLanguage: "auto" follows the browser).

export type UiLang = "en" | "zh-CN" | "es" | "pt-BR" | "ja" | "de" | "fr" | "ko" | "it" | "tr" | "vi" | "id" | "zh-TW" | "pl" | "nl" | "th" | "ar" | "ru" | "uk" | "hi" | "cs" | "ms" | "fil" | "ro" | "hu" | "el" | "he" | "sv" | "da" | "no" | "fi";

const UI_LANGS: readonly UiLang[] = ["en", "zh-CN", "es", "pt-BR", "ja", "de", "fr", "ko", "it", "tr", "vi", "id", "zh-TW", "pl", "nl", "th", "ar", "ru", "uk", "hi", "cs", "ms", "fil", "ro", "hu", "el", "he", "sv", "da", "no", "fi"];

export function resolveUiLang(pref: string | undefined, browserLocale: string | undefined): UiLang {
  if (pref && (UI_LANGS as readonly string[]).includes(pref)) return pref as UiLang;
  const bl = (browserLocale ?? "").toLowerCase();
  // Traditional before simplified: "zh-TW", "zh-HK", "zh-MO" and "zh-Hant" all start
  // with "zh", and a single simplified branch would hand those readers a script they
  // do not read.
  if (bl.startsWith("zh")) return /^zh-(tw|hk|mo|hant)/.test(bl) ? "zh-TW" : "zh-CN";
  if (bl.startsWith("pt")) return "pt-BR";
  if (bl.startsWith("es")) return "es";
  if (bl.startsWith("ja")) return "ja";
  if (bl.startsWith("de")) return "de";
  if (bl.startsWith("fr")) return "fr";
  if (bl.startsWith("ko")) return "ko";
  if (bl.startsWith("it")) return "it";
  if (bl.startsWith("tr")) return "tr";
  if (bl.startsWith("vi")) return "vi";
  // Indonesian is "id", but older Chrome builds still report the legacy "in".
  if (bl.startsWith("id") || bl.startsWith("in")) return "id";
  if (bl.startsWith("pl")) return "pl";
  if (bl.startsWith("nl")) return "nl";
  if (bl.startsWith("th")) return "th";
  if (bl.startsWith("ar")) return "ar";
  if (bl.startsWith("ru")) return "ru";
  if (bl.startsWith("uk")) return "uk";
  if (bl.startsWith("hi")) return "hi";
  if (bl.startsWith("cs")) return "cs";
  // Malay: "ms" itself, and the "ms-MY"/"ms-BN" regional tags.
  if (bl.startsWith("ms")) return "ms";
  // Filipino is "fil", and older Chrome builds still report the legacy "tl" for
  // the same language. Finnish will match the "fi" prefix this starts with, so
  // that branch has to sit below this one.
  if (bl.startsWith("fil") || bl.startsWith("tl")) return "fil";
  if (bl.startsWith("ro")) return "ro";
  if (bl.startsWith("hu")) return "hu";
  if (bl.startsWith("el")) return "el";
  // Hebrew: "he" is the current code, "iw" the legacy one Chrome used to report.
  if (bl.startsWith("he") || bl.startsWith("iw")) return "he";
  if (bl.startsWith("sv")) return "sv";
  if (bl.startsWith("da")) return "da";
  // Norwegian: "no" is the tag we ship, Chrome reports Bokmål as "nb", and
  // Nynorsk ("nn") gets the same strings rather than dropping to English.
  if (bl.startsWith("nb") || bl.startsWith("nn") || bl.startsWith("no")) return "no";
  // Finnish sits below Filipino's "fil" branch above, which owns the same prefix.
  if (bl.startsWith("fi")) return "fi";
  return "en";
}

// Right-to-left scripts, by language tag. The three UI shells read this instead
// of testing for Arabic, which is what they used to do — Hebrew is a direction
// this product ships into, and the direction of a language belongs to the
// language, not to the string table it happens to have landed in. The tag is
// listed here even while its strings are still being imported.
const RTL_LANGS = ["ar", "he"] as const;

export function isRtl(lang: string): boolean {
  return (RTL_LANGS as readonly string[]).includes(lang);
}

